 types=dict(sbyte='System.SByte',short='System.Int16',int='System.Int32',long='System.Int64',bool='System.Boolean',char='System.Char',string='System.String',float='System.Single',double='System.Double');seen=set();vectors=[];counts=collections.Counter(x['kind'] for x in plan['profiles']);assert counts['float']>=4096 and counts['double']>=4096
